// SubscriberHandle — interface that the MCP transport implements to represent
// ONE open `subscriptions/listen` stream. Inversion of dependency: the
// notifications domain does not know the MCP SDK or the HTTP server; the
// transport wraps the stream's response behind this interface and passes it to
// `presenceRegistry.subscribe`. One handle = one stream = one registry entry.
//
// Contract (Waggle Pipeline + Presence Registry § "presence/subscriber-handle.ts"):
//   - `connectionId` is generated by the transport when it accepts the stream
//     and is globally unique within the process. The registry only uses it as
//     the key of its per-participant Map; two handles sharing one id make the
//     second subscribe replace the first.
//   - `deliver` writes exactly one event to the stream. On a failed write the
//     handle MUST already have closed itself (reason `write_failed`) and fired
//     its `onClose` callbacks before rejecting.
//   - `close` is the forced shutdown initiated by the domain (LRU, revocation,
//     suspension, process shutdown). It never throws, is idempotent, ends the
//     stream visibly for the client so it reconnects, releases timers and
//     listeners, and then fires `onClose` once with the same reason.
//   - `onClose` callbacks fire EXACTLY ONCE when the stream ends for any cause.
//     A callback registered on an already-closed handle fires immediately.
//   - Detecting a dead network path (keep-alive writes, stalled-drain timer, the
//     lease a client may ask for) is the handle's job. The registry never probes
//     and never runs timers.

import type { IdentityContext, UUIDv7 } from '#domain/auth/types.js';

import type { WaggleNotification } from '#domain/notifications/waggle/types.js';

export type StreamCloseReason =
  | 'client_closed'
  | 'write_failed'
  | 'stalled'
  | 'credential_expired'
  | 'participant_revoked'
  | 'participant_suspended'
  // ADR-026: the enrollment Worker was retired with the stream open.
  | 'participant_retired'
  | 'evicted_lru'
  | 'shutdown'
  | 'replay_failed'
  | 'lease_expired';

export interface SubscriberHandle {
  readonly connectionId: UUIDv7;
  readonly callerContext: IdentityContext;
  deliver(notification: WaggleNotification): Promise<void>;
  close(reason: StreamCloseReason): void;
  onClose(callback: (reason: StreamCloseReason) => void): void;
}
